<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class auxiliary extends lib { var $options; public function __construct() { add_action( 'qqworld-collector-settings-image-fields', array($this, 'add_fields') ); add_filter('manage_posts_columns', array($this, 'manage_posts_columns'), 10, 2 ); add_action('manage_posts_custom_column', array($this, 'manage_posts_custom_column'), 10, 2); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); } public function init() {} public function admin_enqueue_scripts() { global $pagenow; if ($pagenow == 'edit.php') { wp_enqueue_style( 'qqworld-collector-auxiliary-settings'); } } public function manage_posts_columns($posts_columns, $post_type) { $type = get_post_type_object($post_type); if (!$type->public || in_array($post_type, array('product'))) return $posts_columns; if ($this->options->qc_auxiliary_settings_featured_image) { $insert_array = array( 'featured-image' => __('Featured Image', $this->text_domain) ); $first_array = array_splice($posts_columns, 0, 2); $posts_columns = array_merge($first_array, $insert_array, $posts_columns); } if ($this->options->qc_auxiliary_settings_uploaded_images) { $posts_columns['uploaded-images'] = __('Uploaded Images', $this->text_domain); } if ($this->options->qc_auxiliary_settings_inner_images) { $posts_columns['inner-images'] = __('Inner Images', $this->text_domain); } return $posts_columns; } public function manage_posts_custom_column($column_name, $post_ID) { global $post; switch ($column_name) { case 'featured-image': if ($this->options->qc_auxiliary_settings_featured_image) { if (has_post_thumbnail()) print get_the_post_thumbnail($post->ID, 'thumbnail', array( 'class' => "qqworld-column-{$column_name}" ) ); else print '<img class="qqworld-column-'.$column_name.'" src="'.QQWORLD_COLLECTOR_URL.'images/no-photo.png" />'; } break; case 'uploaded-images': if ($this->options->qc_auxiliary_settings_uploaded_images) : $attachments = get_attached_media( 'image', $post_ID ); $has_attachments = !empty($attachments); if ($has_attachments) : ?>
					<ul class="qqworld-column-images">
					<?php foreach ($attachments as $attachment_id => $attachment) : $full = wp_get_attachment_image_src($attachment_id, 'full'); $thumbnail = wp_get_attachment_image_src($attachment_id, 'thumbnail'); ?>
						<li><a href="<?php echo $full[0]; ?>" rel="lightbox[attachment-uploaded]" target="_blank"><img src="<?php echo $thumbnail[0]; ?>" /></a></li>
					<?php endforeach; ?>
					</ul>
					<?php endif; endif; break; case 'inner-images': if ($this->options->qc_auxiliary_settings_inner_images) : preg_match_all('/<img.*?(?: |\\t|\\r|\\n)?src=[\'"]?(.+?)[\'"]?(?:(?: |\\t|\\r|\\n)+.*?)?>/sim', $post->post_content, $strResult, PREG_PATTERN_ORDER); if (count($strResult[1])) : ?>
					<ul class="qqworld-column-images">
					<?php foreach ($strResult[1] as $image) : ?>
						<li><a href="<?php echo $image; ?>" rel="lightbox[attachment-inner]" target="_blank"><img src="<?php echo $image; ?>" /></a></li>
					<?php endforeach; ?>
					</ul>
					<?php endif; endif; break; } } public function add_fields($settings) { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'settings-auxiliary.php'; } } ?>